-- Team Commissions rollback; exact separately approved SQL Editor package.
-- EXTERNAL TARGET CHECK REQUIRED: Supabase project jncvvsvckxhqgqvkppmj.
-- The database name 'postgres' is NOT project identity. Verify the dashboard/tool project binding.
-- No production execution is authorized by generating or testing this file.
-- Atomic and replay-refusing. On uncertain outcome, inspect history/functions; never blindly retry.
-- Removes only the exact guarded migration-history row; financial/business rows are untouched.
BEGIN;
SET LOCAL lock_timeout='1s';
SET LOCAL statement_timeout='180s';
LOCK TABLE supabase_migrations.schema_migrations IN SHARE ROW EXCLUSIVE MODE;
DO $team_commissions_release$
DECLARE
  reviewed_sql text := convert_from(decode('','base64'),'UTF8');
  reviewed_hash text := '6c6a6cb2cc61d903624a91f1e65c5433dfeae0f887a164d5d530bf31b2cf34d0';
  r record;
BEGIN
  IF current_user <> 'postgres' THEN
    RAISE EXCEPTION 'Use the separately approved database operator context' USING ERRCODE='42501';
  END IF;
  IF encode(sha256(convert_to(reviewed_sql,'UTF8')),'hex') IS DISTINCT FROM reviewed_hash THEN
    RAISE EXCEPTION 'Embedded SQL differs from approved bytes' USING ERRCODE='55000';
  END IF;
  IF (SELECT max(version) FROM supabase_migrations.schema_migrations) IS DISTINCT FROM '20261112165503'
     OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations
        WHERE version='20261112165503' AND name='policy_commission_scoped_reads' AND cardinality(statements)=1
          AND encode(sha256(convert_to(statements[1],'UTF8')),'hex')='0118728fde1d70d45c6595745a15109f997674e3801b608e037fd7f618debff1') THEN
    RAISE EXCEPTION 'Recovery history differs from the exact approved release' USING ERRCODE='55000';
  END IF;
  EXECUTE reviewed_sql;
  DELETE FROM supabase_migrations.schema_migrations
    WHERE version='20261112165503' AND name='policy_commission_scoped_reads' AND cardinality(statements)=1
      AND encode(sha256(convert_to(statements[1],'UTF8')),'hex')='0118728fde1d70d45c6595745a15109f997674e3801b608e037fd7f618debff1';
  IF NOT FOUND OR to_regnamespace('policy_commission_scoped') IS NOT NULL
     OR (SELECT max(version) FROM supabase_migrations.schema_migrations) IS DISTINCT FROM '20261111192142' THEN
    RAISE EXCEPTION 'Recovery metadata readback failed' USING ERRCODE='55000';
  END IF;
END $team_commissions_release$;
COMMIT;
